import React from "react";
import withNavigation from "../utils/withNavigation";
import LeftSlidebar from "./leftSlidebar";
import axiosInstance from "../configurations/instance";

class EventsList extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      events: [],
    };
  }

  componentDidMount() {
    axiosInstance
      .get("/event/all-events") 
      .then((response) => {
        this.setState({ events: response.data });
      })
      .catch((error) => console.error("Ошибка при загрузке событий:", error));
  }

  handleView = (id) => {
    console.log("Просмотр события с ID:", id);
    this.props.navigate(`/event/${id}`);
  };

  handleEdit = (id) => {
    console.log("Изменение события с ID:", id);
    this.props.navigate(`/edit-event/${id}`); 
  };

  handleDelete = (id) => {
    if (window.confirm("Вы уверены, что хотите удалить это событие?")) {
      axiosInstance
        .delete(`/event/${id}`)
        .then(() => {
          this.setState((prevState) => ({
            events: prevState.events.filter((event) => event._id !== id),
          }));
          alert("Событие успешно удалено.");
        })
        .catch((error) => {
          console.error("Ошибка при удалении события:", error);
          alert("Не удалось удалить событие.");
        });
    }
  };

  render() {
    return (
      <div className="creating-page">
        <header className="main-header"></header>
        <div className="profile-page">
          <LeftSlidebar />
          <div className="content">
            <h1>Список событий</h1>
            <table className="event-table">
              <thead>
                <tr>
                  <th>№</th>
                  <th>Название</th>
                  <th>Время проведения</th>
                  <th>Действия</th>
                </tr>
              </thead>
              <tbody>
                {this.state.events.map((event, index) => (
                  <tr key={event._id}>
                    <td>{index + 1}</td>
                    <td>{event.eventName}</td>
                    <td>{new Date(event.eventDate).toLocaleDateString()}</td>
                    <td>
                      <button caonClick={() => this.handleView(event._id)}>
                        Просмотр
                      </button>
                      <button onClick={() => this.handleEdit(event._id)}>
                        Изменить
                      </button>
                      <button onClick={() => this.handleDelete(event._id)}>
                        Удалить
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  }
}

export default withNavigation(EventsList);
